def combinationSum4(nums, target):
    # dp[i] = number of combinations to sum up to i
    dp = [0] * (target + 1)
    dp[0] = 1  # One way to make 0: use nothing

    # For every sum from 1 to target
    for t in range(1, target + 1):
        # Try adding each number
        for num in nums:
            if t >= num:
                dp[t] += dp[t - num]
    return dp[target]
